const repair=(id,requires,title,story,task,starter,solution,checks,extra={})=>({id,kind:'clock',requires,title,story,task,starter,solution,checks,xp:150+requires*5,coins:70+requires*2,hint:'Try a tiny example by hand. Compare what the mechanism should do with what each line actually does.',...extra});
export const clockProjects=[
  repair('clock-latch',0,'Rowan’s kitchen clock',
    'Rowan timed his first batch of honey buns by this little clock. Mira found a worn latch inside. It should tick only when its spring is wound AND its case is latched.',
    'Write can_tick(wound, latched). Return True only when both boolean inputs are True.',
    'def can_tick(wound, latched):\n    return wound or latched',
    'def can_tick(wound, latched):\n    return wound and latched',
    'f=scope.get("can_tick")\nassert callable(f)\nfor w,l in [(True,True),(True,False),(False,True),(False,False)]:\n    assert f(w,l) is (w and l), "Both the spring and latch must be ready."',
    {inspection:'The spring is wound, but the case is open. Should the clock tick?',choices:['Yes, one ready part is enough.','No, both conditions must be true.','Only on Tuesdays.'],answer:1,feedback:['That is what or would allow. This latch needs both conditions.','Exactly. The two conditions work together with and.','The day is not part of this mechanism.'],demo:'{"wound_and_closed": can_tick(True, True), "wound_but_open": can_tick(True, False)}',outcome:'The kitchen clock ticks again. Rowan marks the back: “For all the mornings still to come.”',object:'clock'}),
  repair('clock-hours',4,'The clock that forgot twelve',
    'The library’s little dial always stopped at eleven. Nell remembers waiting beneath it for her first borrowed book. Mira asks you to follow the hours around the face.',
    'Write next_hours(start, count). Return count consecutive clock hours INCLUDING start, wrapping 12 to 1. start is 1–12 and count is a nonnegative integer. Zero count returns [].',
    'def next_hours(start, count):\n    return list(range(start, start + count))',
    'def next_hours(start, count):\n    return [(start - 1 + step) % 12 + 1 for step in range(count)]',
    'f=scope.get("next_hours")\nassert callable(f)\nfor start,count in [(11,4),(12,3),(1,0),(3,15),(7,1)]:\n    assert f(start,count)==[(start-1+i)%12+1 for i in range(count)], "Keep the starting hour, then wrap twelve back to one."',
    {previous:'clock-latch',inspection:'Trace four steps starting at 11. Which hours should the dial visit?',choices:['11, 12, 1, 2','12, 1, 2, 3','11, 12, 13, 14'],answer:0,feedback:['Yes. The starting hour counts as the first step.','That skips the starting hour.','Clock faces wrap after twelve.'],demo:'next_hours(11, 6)',outcome:'The library dial makes a full turn. Nell saves the old eleven-o’clock mark as a reminder to test the edges.',object:'dial'}),
  repair('clock-melody',12,'June’s little music box',
    'Elio brings the music box June played while labelling seedlings. Its paper melody is dusty and its brass cylinder still. Mira separates the repair into three small functions.',
    'Write clean_notes(notes): strip spaces and uppercase each string. Write repeat_notes(notes, repeats): repeat the list, treating negative repeats as zero. Write make_melody(notes, repeats): call clean_notes, then repeat_notes. Return the resulting list. Do not change the original notes.',
    'def clean_notes(notes):\n    return notes\n\ndef repeat_notes(notes, repeats):\n    return notes\n\ndef make_melody(notes, repeats):\n    return []',
    'def clean_notes(notes):\n    return [note.strip().upper() for note in notes]\n\ndef repeat_notes(notes, repeats):\n    return notes * max(repeats, 0)\n\ndef make_melody(notes, repeats):\n    return repeat_notes(clean_notes(notes), repeats)',
    'for name in ["clean_notes","repeat_notes","make_melody"]:\n    assert callable(scope.get(name)), "Keep all three small functions."\nassert scope["clean_notes"]([" c ","g"])==["C","G"]\nassert scope["repeat_notes"](["A"],3)==["A"]*3\nfor notes,n in [([" c ","e"," G "],2),([],3),(["d"],0),(["A"],-1)]:\n    before=notes.copy()\n    assert scope["make_melody"](notes,n)==[v.strip().upper() for v in notes]*max(0,n), "Clean the notes before repeating them."\n    assert notes==before, "Keep June’s original melody unchanged."\n_calls=[]\nfor name in ["clean_notes","repeat_notes"]:\n    original=scope[name]\n    def spy(*args,_fn=original,_name=name):\n        _calls.append(_name)\n        return _fn(*args)\n    scope[name]=spy\nscope["make_melody"]([" c "],2)\nassert _calls==["clean_notes","repeat_notes"], "Let make_melody call the two helpers in order."',
    {previous:'clock-hours',inspection:'Which kind of work belongs in clean_notes?',choices:['Playing sound.','Deciding how many times to repeat.','Tidying the spelling of each note.'],answer:2,feedback:['Sound is the final performance, after the data is ready.','That belongs in repeat_notes.','Yes. Each function has one clear job.'],order:['clean_notes','repeat_notes','play_melody'],demo:'make_melody([" c ", "e", " G ", "e"], 2)',outcome:'June’s tune fills the workroom again. Elio can almost hear her humming over the seed trays.',object:'music'}),
  repair('clock-round',24,'A village keeping time together',
    'Four neighbours bring their clocks to Mira’s bench. Each one chimes at its own interval. A shared schedule will help Mira hear which mechanisms still need attention.',
    'Write chime_schedule(clocks, end). clocks maps names to positive integer intervals. Return {minute: sorted names} at every chime from minute 1 through end INCLUSIVE. Omit silent minutes. Raise ValueError for any interval <= 0; do not change clocks.',
    'def chime_schedule(clocks, end):\n    schedule = {}\n    return schedule',
    'def chime_schedule(clocks, end):\n    if any(interval <= 0 for interval in clocks.values()):\n        raise ValueError("Intervals must be positive")\n    schedule = {}\n    for minute in range(1, end + 1):\n        names = sorted(name for name, interval in clocks.items() if minute % interval == 0)\n        if names:\n            schedule[minute] = names\n    return schedule',
    'f=scope.get("chime_schedule")\nassert callable(f)\nfor clocks,end in [({"Kitchen":2,"Library":3},6),({},5),({"A":1},0),({"Z":2,"A":2},4)]:\n    before=clocks.copy();expected={}\n    for minute in range(1,end+1):\n        names=sorted(k for k,v in clocks.items() if minute%v==0)\n        if names: expected[minute]=names\n    assert f(clocks,end)==expected, "Include the final minute and every clock that chimes together."\n    assert clocks==before\nfor bad in [0,-2]:\n    try: f({"Broken":bad},3)\n    except ValueError: continue\n    raise AssertionError("Reject nonpositive intervals.")',
    {previous:'clock-melody',inspection:'One clock chimes every 2 minutes, another every 3. What happens at minute 6?',choices:['Only the first chimes.','Both chime; the report needs both names.','Neither chimes.'],answer:1,feedback:['Six is divisible by both intervals.','Exactly. One minute can contain several events.','Trace the multiples of two and three.'],demo:'chime_schedule({"Kitchen":2,"Library":3,"Greenhouse":4}, 12)',outcome:'Four repaired keepsakes keep time together. Mira hangs a new label on the bench: “Nothing loved is too small to mend.”',object:'round'})
];
